// hitchfix: repair OBS skipped-frame hitches in a 30 fps game recorded at 60 fps, touching only the hitches.
// Normal cadence: each game frame appears in 2 consecutive 60 fps slots. When OBS skipped frames, a game frame is held
// for 3+ slots and the next real frame arrives late (motion jumps). For every held run longer than 2 slots, the extra
// slots get frames generated by Apple's VTLowLatencyFrameInterpolation between the held frame and the next real one.
// Every other frame is the untouched original. Video only (mux audio back with ffmpeg).
// Usage: hitchfix <in.mp4> <out.mov> [start_s] [dur_s]
#import <AVFoundation/AVFoundation.h>
#import <VideoToolbox/VideoToolbox.h>
#import <Accelerate/Accelerate.h>

static const int IW = 1920, IH = 1080;  // interpolator max on this Mac (M3 Pro, macOS 27): 1920 px / 1080p

static CVPixelBufferRef make(NSDictionary *attrs, int w, int h, OSType fmt) {
  NSMutableDictionary *a = [attrs ?: @{} mutableCopy];
  a[(id)kCVPixelBufferIOSurfacePropertiesKey] = @{};
  CVPixelBufferRef b = NULL;
  CVPixelBufferCreate(NULL, w, h, fmt, (__bridge CFDictionaryRef)a, &b);
  return b;
}

// mean absolute luma difference on a 1/8 subsampled grid (0..255)
static double lumaDiff(CVPixelBufferRef a, CVPixelBufferRef b) {
  CVPixelBufferLockBaseAddress(a, kCVPixelBufferLock_ReadOnly); CVPixelBufferLockBaseAddress(b, kCVPixelBufferLock_ReadOnly);
  const uint8_t *pa = CVPixelBufferGetBaseAddressOfPlane(a, 0), *pb = CVPixelBufferGetBaseAddressOfPlane(b, 0);
  size_t sa = CVPixelBufferGetBytesPerRowOfPlane(a, 0), sb = CVPixelBufferGetBytesPerRowOfPlane(b, 0);
  size_t w = CVPixelBufferGetWidthOfPlane(a, 0), h = CVPixelBufferGetHeightOfPlane(a, 0);
  double sum = 0; long n = 0;
  for (size_t y = 0; y < h; y += 8) for (size_t x = 0; x < w; x += 8) { sum += abs((int)pa[y * sa + x] - (int)pb[y * sb + x]); n++; }
  CVPixelBufferUnlockBaseAddress(a, kCVPixelBufferLock_ReadOnly); CVPixelBufferUnlockBaseAddress(b, kCVPixelBufferLock_ReadOnly);
  return sum / n;
}

// 0..1 histogram distance (half L1 of 64-bin luma histograms): ~0 same shot, large for a camera cut
static double histDiff(CVPixelBufferRef a, CVPixelBufferRef b) {
  double ha[64] = {0}, hb[64] = {0}; long n = 0;
  CVPixelBufferRef bufs[2] = {a, b}; double *hs[2] = {ha, hb};
  for (int k = 0; k < 2; k++) {
    CVPixelBufferLockBaseAddress(bufs[k], kCVPixelBufferLock_ReadOnly);
    const uint8_t *p = CVPixelBufferGetBaseAddressOfPlane(bufs[k], 0); size_t st = CVPixelBufferGetBytesPerRowOfPlane(bufs[k], 0);
    size_t w = CVPixelBufferGetWidthOfPlane(bufs[k], 0), h = CVPixelBufferGetHeightOfPlane(bufs[k], 0); n = 0;
    for (size_t y = 0; y < h; y += 8) for (size_t x = 0; x < w; x += 8) { hs[k][p[y * st + x] >> 2]++; n++; }
    CVPixelBufferUnlockBaseAddress(bufs[k], kCVPixelBufferLock_ReadOnly);
  }
  double d = 0; for (int i = 0; i < 64; i++) d += fabs(ha[i] - hb[i]);
  return d / (2.0 * n);
}

int main(int argc, char **argv) { @autoreleasepool {
  if (argc < 3) { printf("usage: hitchfix in.mp4 out.mov [start] [dur]\n"); return 2; }
  NSString *inPath = @(argv[1]), *outPath = @(argv[2]);
  double start = argc > 3 ? atof(argv[3]) : 0, dur = argc > 4 ? atof(argv[4]) : 0;
  double dupThresh = 0.6;
  double cutThresh = argc > 5 ? atof(argv[5]) : 0.25;  // luma histogram change that means a different shot  // calibrated: identical repeats score ~0, any real game motion scores well above 1
  NSError *err = nil;

  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:inPath] options:nil];
  AVAssetTrack *vt = [asset tracksWithMediaType:AVMediaTypeVideo][0];
  int W = (int)vt.naturalSize.width, H = (int)vt.naturalSize.height;
  AVAssetReader *r = [AVAssetReader assetReaderWithAsset:asset error:&err];
  if (dur > 0) r.timeRange = CMTimeRangeMake(CMTimeMakeWithSeconds(start, 60000), CMTimeMakeWithSeconds(dur, 60000));
  AVAssetReaderTrackOutput *o = [AVAssetReaderTrackOutput assetReaderTrackOutputWithTrack:vt outputSettings:@{
    (id)kCVPixelBufferPixelFormatTypeKey: @(kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange), (id)kCVPixelBufferIOSurfacePropertiesKey: @{}}];
  o.alwaysCopiesSampleData = NO; [r addOutput:o]; [r startReading];

  VTLowLatencyFrameInterpolationConfiguration *cfg =
      [[VTLowLatencyFrameInterpolationConfiguration alloc] initWithFrameWidth:IW frameHeight:IH numberOfInterpolatedFrames:1];
  VTFrameProcessor *proc = [VTFrameProcessor new];
  if (![proc startSessionWithConfiguration:cfg error:&err]) { printf("interpolator: %s\n", err.description.UTF8String); return 1; }
  VTPixelTransferSessionRef xfer; VTPixelTransferSessionCreate(NULL, &xfer);

  [[NSFileManager defaultManager] removeItemAtPath:outPath error:nil];
  AVAssetWriter *w = [AVAssetWriter assetWriterWithURL:[NSURL fileURLWithPath:outPath] fileType:AVFileTypeQuickTimeMovie error:&err];
  AVAssetWriterInput *wi = [AVAssetWriterInput assetWriterInputWithMediaType:AVMediaTypeVideo outputSettings:@{
    AVVideoCodecKey: AVVideoCodecTypeHEVC, AVVideoWidthKey: @(W), AVVideoHeightKey: @(H),
    AVVideoCompressionPropertiesKey: @{AVVideoAverageBitRateKey: @(40000000)},
    AVVideoColorPropertiesKey: @{AVVideoColorPrimariesKey: AVVideoColorPrimaries_ITU_R_709_2,
                                 AVVideoTransferFunctionKey: AVVideoTransferFunction_ITU_R_709_2, AVVideoYCbCrMatrixKey: AVVideoYCbCrMatrix_ITU_R_709_2}}];
  wi.expectsMediaDataInRealTime = NO;
  AVAssetWriterInputPixelBufferAdaptor *ad = [AVAssetWriterInputPixelBufferAdaptor assetWriterInputPixelBufferAdaptorWithAssetWriterInput:wi sourcePixelBufferAttributes:nil];
  [w addInput:wi]; [w startWriting];
  __block BOOL started = NO;

  // run = consecutive slots showing the same game frame
  NSMutableArray *runBufs = [NSMutableArray array];   // CVPixelBuffer per slot (originals, retained)
  NSMutableArray *runTimes = [NSMutableArray array];  // NSValue CMTime per slot
  CVPixelBufferRef runFrame = NULL;                   // the game frame of the current run
  __block long slots = 0, runsFixed = 0, framesMade = 0, fails = 0, skippedCuts = 0, skippedLong = 0;

  void (^emit)(CVPixelBufferRef, CMTime) = ^(CVPixelBufferRef b, CMTime t) {
    if (!started) { [w startSessionAtSourceTime:t]; started = YES; }
    while (!wi.readyForMoreMediaData) [NSThread sleepForTimeInterval:0.002];
    [ad appendPixelBuffer:b withPresentationTime:t];
  };

  // flush a run; `next` = first frame of the following run (NULL at end of stream)
  void (^flush)(CVPixelBufferRef) = ^(CVPixelBufferRef next) {
    long n = runBufs.count;
    double jump = next ? histDiff((__bridge CVPixelBufferRef)runBufs[0], next) : 0;
    if (getenv("HF_DEBUG") && n > 2 && next) printf("run %ld slots, hist jump %.3f\n", n, jump);
    // leave untouched: normal cadence, end of stream, camera cuts (blending two shots = the "drunk" smear),
    // and long freezes (> 3 missing game frames: too much motion to invent)
    if (n <= 2 || !next || jump > cutThresh || n > 8) {
      if (n > 2 && next) { if (jump > cutThresh) skippedCuts++; else skippedLong++; }
      for (long i = 0; i < n; i++) emit((__bridge CVPixelBufferRef)runBufs[i], [runTimes[i] CMTimeValue]);
    } else {  // hitch: keep the first 2 slots, generate the rest moving towards the next real frame
      runsFixed++;
      CVPixelBufferRef a = make(cfg.sourcePixelBufferAttributes, IW, IH, kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange);
      CVPixelBufferRef b = make(cfg.sourcePixelBufferAttributes, IW, IH, kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange);
      VTPixelTransferSessionTransferImage(xfer, (__bridge CVPixelBufferRef)runBufs[0], a);
      VTPixelTransferSessionTransferImage(xfer, next, b);
      CMTime t0 = [runTimes[0] CMTimeValue], tn = [runTimes[n - 1] CMTimeValue];
      for (long i = 0; i < n; i++) {
        CMTime t = [runTimes[i] CMTimeValue];
        if (i < 2) { emit((__bridge CVPixelBufferRef)runBufs[i], t); continue; }
        // the run spans n slots + 1 more until `next`; the game frame should advance linearly across them
        float phase = (float)(i - 1) / (float)(n - 1);  // held slots 2..n-1 -> evenly spaced phases in (0,1)
        CVPixelBufferRef d = make(cfg.destinationPixelBufferAttributes, IW, IH, kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange);
        VTFrameProcessorFrame *fa = [[VTFrameProcessorFrame alloc] initWithBuffer:a presentationTimeStamp:t0];
        VTFrameProcessorFrame *fb = [[VTFrameProcessorFrame alloc] initWithBuffer:b presentationTimeStamp:CMTimeAdd(tn, CMTimeMake(1001, 60000))];
        VTFrameProcessorFrame *fd = [[VTFrameProcessorFrame alloc] initWithBuffer:d presentationTimeStamp:t];
        VTLowLatencyFrameInterpolationParameters *p = [[VTLowLatencyFrameInterpolationParameters alloc]
            initWithSourceFrame:fb previousFrame:fa interpolationPhase:@[@(phase)] destinationFrames:@[fd]];
        NSError *e = nil;
        if ([proc processWithParameters:p error:&e]) {
          CVPixelBufferRef full = make(nil, W, H, kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange);
          VTPixelTransferSessionTransferImage(xfer, d, full);
          emit(full, t); CVPixelBufferRelease(full); framesMade++;
        } else {
          if (fails++ < 3) printf("interpolate failed: %s\n", e.description.UTF8String);
          emit((__bridge CVPixelBufferRef)runBufs[i], t);
        }
        CVPixelBufferRelease(d);
      }
      CVPixelBufferRelease(a); CVPixelBufferRelease(b);
    }
    [runBufs removeAllObjects]; [runTimes removeAllObjects];
  };

  CMSampleBufferRef sb;
  while ((sb = [o copyNextSampleBuffer])) {
    CVPixelBufferRef src = CMSampleBufferGetImageBuffer(sb);
    CMTime t = CMSampleBufferGetPresentationTimeStamp(sb);
    CVPixelBufferRef copy = make(nil, W, H, kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange);
    VTPixelTransferSessionTransferImage(xfer, src, copy);
    CFRelease(sb); slots++;
    if (runFrame && lumaDiff(runFrame, copy) > dupThresh) {  // new game frame: close the previous run
      flush(copy);
      runFrame = NULL;
    }
    if (!runFrame) runFrame = copy;
    [runBufs addObject:(__bridge id)copy]; [runTimes addObject:[NSValue valueWithCMTime:t]];
    CVPixelBufferRelease(copy);  // runBufs retains it
  }
  flush(NULL);
  [proc endSession];
  [wi markAsFinished];
  dispatch_semaphore_t done = dispatch_semaphore_create(0);
  [w finishWritingWithCompletionHandler:^{ dispatch_semaphore_signal(done); }];
  dispatch_semaphore_wait(done, DISPATCH_TIME_FOREVER);
  printf("skipped: %ld at camera cuts, %ld long freezes\n", skippedCuts, skippedLong);
  printf("slots %ld, hitches fixed %ld, frames generated %ld (%.1f%% of slots), failures %ld, writer status %ld\n",
         slots, runsFixed, framesMade, 100.0 * framesMade / MAX(slots, 1), fails, (long)w.status);
  return w.status == AVAssetWriterStatusCompleted ? 0 : 1;
}}
